UPDATE lessons SET title='Year 3, Week 9, Lesson 4: Fluency: times tables', data=json_patch(data,'{"child_mission":"Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSolve and name backup strategy if needed: 7×2; 6×5; 3×10.\n\nFEEDBACK\n14; 30; 30 — doubles / fives / tens.\n\nWATCH FOR\nSpeed that produces wrong products is not fluency.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nComplete an eighteen-item ×2/5/10 fluency set. Re-work misses with a named strategy and equal-groups sketch.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed.","lesson_number":4,"lesson_role":"Fluency and review","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-MR-01"],"parent_notes":"Parent: Marking guidance for the independent task: Complete an eighteen-item ×2/5/10 fluency set. Re-work misses with a named strategy and equal-groups sketch. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new numbers solved with visible working for fluency; key places/values named. Do not award marks for retyping the model.\n\nParent: Written model 2: Sample misconception: Speed that produces wrong products is not fluency.. Correction uses 14; 30; 30 — doubles / fives / tens.. Why: restores accurate fluency.\n\nParent: Likely misconception: Speed that produces wrong products is not fluency. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses fluency with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with fluency, show corrected working, and say why the correction works.\n\nParent: Marking notes: Accept any mathematically valid solution that uses new numbers, shows working for fluency, and names places/values. Reject copied model numbers. / Accept a named misconception about fluency, corrected working, and a method reason. Reject vague “I was wrong” with no repair..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"This matches the taught method for fluency. The other choices miss a key step or use a common mistake.","options":["A method that skips the key step taught in this lesson","14; 30; 30 — doubles / fives / tens","Speed that produces wrong products is not fluency","A claim that names no evidence from the lesson material"],"question":"Solve and name backup strategy if needed: 7×2; 6×5; 3×10. Which response is most accurate?","type":"multiple_choice"},{"correct_index":1,"explanation":"This is the misconception to avoid for fluency; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Careful use of tables and explain why it matters with clear evidence","Speed that produces wrong products is not fluency","Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed","14; 30; 30 — doubles / fives / tens"],"question":"Which statement is a common mistake when working with fluency?","type":"multiple_choice"},{"correct_index":0,"explanation":"Understanding is shown by new evidence and a named tables and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Apply fluency to new material and name the tables and explain why it matters used","Repeat the worked example wording with no new evidence","Speed that produces wrong products is not fluency","Name tables and explain why it matters only, without linking it to fluency"],"question":"Which response best applies fluency with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"Mathematics answers need labelled working tied to place value, quantity or the asked operation. The other choices miss a key step or use a common mistake.","options":["Change digits to look neater without checking place value","Speed that produces wrong products is not fluency","Show each place, value or step and say why that step is valid","Write only a final number with no working"],"question":"Which working best supports a correct answer for this lesson on fluency?","type":"multiple_choice"},{"correct_index":3,"explanation":"The correct statement applies the taught fluency method; the others break place value, units or the asked quantity. The other choices miss a key step or use a common mistake.","options":["Speed that produces wrong products is not fluency","Read 7 from left to right as ones only, ignoring place value","Ignore units and treat 7 and 2 as interchangeable","14; 30; 30 — doubles / fives / tens"],"question":"Using the method for fluency, which statement is true?","type":"multiple_choice"},{"correct_index":2,"explanation":"Disagreement is resolved by checking places, operations and the question focus, not by blending answers. The other choices miss a key step or use a common mistake.","options":["Delete units so the answers appear to match","Average the two answers without checking either","Recheck places, operations and whether the question asked for the quantity you computed","Pick the longer-looking working automatically"],"question":"If two methods disagree on a fluency problem with numbers such as 7 and 2, what should you check first?","type":"multiple_choice"},{"correct_index":0,"explanation":"Transfer requires new numbers with the same mathematical method and a named reason. The other choices miss a key step or use a common mistake.","options":["Use the same fluency method on new numbers and name the places or values that matter","Retype the worked model numbers 7 and 2 as the answer","Change only handwriting and keep the same numbers","Speed that produces wrong products is not fluency"],"question":"Solve a fresh fluency problem that uses different numbers from the worked model and explain one key step.?","type":"multiple_choice"},{"correct_index":2,"explanation":"Recognising the warned misconception protects accuracy on new problems. The other choices miss a key step or use a common mistake.","options":["14; 30; 30 — doubles / fives / tens","Label units when comparing 7 with 2","Speed that produces wrong products is not fluency","Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed"],"question":"Which error is the lesson warning against for fluency?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept any mathematically valid solution that uses new numbers, shows working for fluency, and names places/values. Reject copied model numbers.","question":"Solve one fresh problem that uses fluency with different numbers from the worked model. Show working and name the places or values that matter.","sample_answer":"Sample: new numbers solved with visible working for fluency; key places/values named. Do not award marks for retyping the model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a named misconception about fluency, corrected working, and a method reason. Reject vague “I was wrong” with no repair.","question":"Describe one likely mistake with fluency, show corrected working, and say why the correction works.","sample_answer":"Sample misconception: Speed that produces wrong products is not fluency.. Correction uses 14; 30; 30 — doubles / fives / tens.. Why: restores accurate fluency.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent working and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-mat-y3-w09-l4","sort_activity":null,"source_note":"Proposed Stage 2 NESA mathematics alignment using verified outcome code wording where recorded in lesson-pipeline/sources; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise fluency.","Read the mission before you start calculating.","Keep the place or unit you are working with in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your working with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the place or distance that carries the method.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore place value or working.","Prefer accurate method over a guess that merely looks neat."],"submit":["Confirm that your working and reason are both present.","Proofread digits, places and operation signs.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact place, value or distance before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key numbers.","Say what each number represents in the method.","A final answer alone is weaker than labelled working."],"teach2":["Compare a weak attempt with stronger working.","Change the value or method, not only how neat it looks.","Name the mistake you are repairing."],"teach3":["Choose fresh numbers that still use the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original working and a short reason.","Save work that shows the skill on new numbers."]},"subject":"Number and Algebra","success_criteria":["I can use fluency with a specific example from this lesson.","I can identify tables and explain why it matters.","I can practise strategy independently on a new prompt.","I can notice accuracy needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":2,"explanation":"Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed.","options":["A guess with no working","A calculation unrelated to the numbers given","Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about fluency with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nSet: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10.\n\nTRY FIRST\nSolve and name backup strategy if needed: 7×2; 6×5; 3×10.\n\nFEEDBACK\n14; 30; 30 — doubles / fives / tens.","explain":"Times-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Speed that produces wrong products is not fluency. Correct the value or method, not just the appearance of the digits.","title":"Understand and model","visual":[{"alt":"Times-table fluency with strategy backup.","caption":"Accuracy before speed.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fluency set</text><text x=\"28\" y=\"78\">×2; ×5; ×10</text><text x=\"358\" y=\"42\">Backup</text><text x=\"358\" y=\"78\">rebuild with a strategy</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which number or place matters most.","who":"pip"},{"text":"Name the places, values or distances that carry the method before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Set: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10. Then write your own working.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which number or place matters most.\nJuno: Name the places, values or distances that carry the method before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Set: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10. Then write your own working."}}]},{"check":{"correct_index":3,"explanation":"Make the method visible: name the values, places or steps you used and say why that step is valid.","options":["A calculation unrelated to the numbers given","An answer copied without understanding","A guess with no working","Make the method visible: name the values, places or steps you used and say why that step is valid"],"question":"Which choice best applies this lesson idea about fluency with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nSet: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10. Look at each number, place or distance that carries the method.\n\nTRY FIRST\nWrite the key numbers from the model and say what each one represents in the method.\n\nFEEDBACK\nThe most useful working names the quantities and the reason for each step, not only the final answer.","explain":"Make the method visible: name the values, places or steps you used and say why that step is valid.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only the final answer without working does not show the method. Correct the value or method, not just the appearance of the digits.","title":"Show the working","visual":[{"alt":"Missed fact rebuilt with groups and strategy.","caption":"Blank memory is a cue to rebuild.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Miss</text><text x=\"28\" y=\"78\">sketch equal groups</text><text x=\"358\" y=\"42\">Then</text><text x=\"358\" y=\"78\">named strategy rewrite</text></g></svg>"}]},{"check":{"correct_index":1,"explanation":"Use an intentionally incorrect attempt as a comparison.","options":["An answer copied without understanding","Use an intentionally incorrect attempt as a comparison","A guess with no working","A calculation unrelated to the numbers given"],"question":"Which choice best applies this lesson idea about fluency with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nSpeed that produces wrong products is not fluency. Here is a more productive model: Set: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10.\n\nTRY FIRST\nDescribe why the warned-against approach gives the wrong value or meaning, then write corrected working.\n\nFEEDBACK\n14; 30; 30 — doubles / fives / tens.","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the answer without repairing the method does not fix the error. Speed that produces wrong products is not fluency. Correct the value or method, not just the appearance of the digits.","title":"Test a misconception"},{"check":{"correct_index":2,"explanation":"Use the method on new numbers or a new context, not a copy of the worked example.","options":["A guess with no working","A calculation unrelated to the numbers given","Use the method on new numbers or a new context, not a copy of the worked example","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about fluency with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nTimes-table fluency for known facts uses strategy backup when memory blanks, with accuracy before speed. Now choose different numbers to show you can transfer the method.\n\nTRY FIRST\nSolve one fresh problem that uses the same skill and write a short reason for your answer.\n\nFEEDBACK\nThe new problem should use the same method as the model, but contain different numbers.","explain":"Use the method on new numbers or a new context, not a copy of the worked example. Review accuracy and units or places.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new numbers. Correct the value or method, not just the appearance of the digits.","title":"Transfer to a new problem"}],"title":"Year 3, Week 9, Lesson 4: Fluency: times tables","unit_number":3,"unit_title":"Multiplication and division","week":9,"week_in_unit":1,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nSet: 6×2; 8×5; 9×10. If 8×5 blanks, rebuild with five-counts or half of 8×10.\n\nWrite what makes this example accurate, naming the places, values or distances used.","worked_visuals":[{"alt":"Times-table fluency with strategy backup.","caption":"Accuracy before speed.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fluency set</text><text x=\"28\" y=\"78\">×2; ×5; ×10</text><text x=\"358\" y=\"42\">Backup</text><text x=\"358\" y=\"78\">rebuild with a strategy</text></g></svg>"},{"alt":"Missed fact rebuilt with groups and strategy.","caption":"Blank memory is a cue to rebuild.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Miss</text><text x=\"28\" y=\"78\">sketch equal groups</text><text x=\"358\" y=\"42\">Then</text><text x=\"358\" y=\"78\">named strategy rewrite</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-mat-y3-w09-l4' AND family_id IS NULL;
